/*!
 * depd shim for ionpower-node (SpiderMonkey 45 lacks V8 structured stack API).
 * Provides a no-op deprecation function — warnings are silenced, which is
 * fine for a demo runtime. The real depd would print deprecation notices
 * to stderr; we simply skip them.
 */

'use strict';

module.exports = depd;

function depd(namespace) {
    function deprecate(message) {
        // no-op: SpiderMonkey 45 doesn't support V8 callSite.getFileName()
    }
    deprecate._file = '<unknown>';
    deprecate._ignored = true;
    deprecate._namespace = namespace;
    deprecate._traced = false;
    deprecate._warned = Object.create(null);
    deprecate.function = function wrapfunction(fn, message) { return fn; };
    deprecate.property = function wrapproperty(obj, prop, message) {};
    return deprecate;
}
